"""python/dftracer/utils/_trace_lazy.py is generated by
scripts/gen_trace_lazy.py from the LazyFrame signatures: the committed file
must equal the generator's output. Regenerate with
`python scripts/gen_trace_lazy.py` from the repository root."""

import shutil
import subprocess
import sys
from pathlib import Path

import pytest

_ROOT = Path(__file__).resolve().parents[2]
_SCRIPT = _ROOT / "scripts" / "gen_trace_lazy.py"
_COMMITTED = _ROOT / "python" / "dftracer" / "utils" / "_trace_lazy.py"

pytestmark = pytest.mark.skipif(
    shutil.which("uvx") is None, reason="uvx not available to format the output"
)


def _generate(out: Path) -> None:
    run = subprocess.run(
        [sys.executable, str(_SCRIPT), "--out", str(out)],
        capture_output=True,
        text=True,
        cwd=_ROOT,
    )
    assert run.returncode == 0, run.stderr


def _is_current(committed: Path, tmp_path: Path) -> bool:
    out = tmp_path / "generated.py"
    _generate(out)
    return out.read_text(encoding="utf-8") == committed.read_text(encoding="utf-8")


def test_committed_trace_lazy_matches_the_generator(tmp_path):
    assert _is_current(_COMMITTED, tmp_path), (
        "_trace_lazy.py is stale: run `python scripts/gen_trace_lazy.py`"
    )


def test_an_edited_trace_lazy_is_detected(tmp_path):
    text = _COMMITTED.read_text(encoding="utf-8")
    edited = tmp_path / "edited.py"
    edited.write_text(
        text.replace("return self.lazy()", "return self.lazy().head()", 1), encoding="utf-8"
    )
    assert edited.read_text(encoding="utf-8") != text
    assert not _is_current(edited, tmp_path)
